author={Shamik Kundu and Sanjay Das and Sayar Karmakar and Arnab Raha and Souvik Kundu and Yiorgos Makris and Kanad Basu},
journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=nB8foAclpo},
note={}
}'}, 'assigned_action_editor': {'value': '~Robert_Legenstein1'}, 'paperhash': {'value': 'kundu|bitbybit_investigating_the_vulnerabilities_of_binary_neural_networks_to_adversarial_bit_flipping'}}

{'title': {'value': 'Intriguing Properties of Hyperbolic Embeddings in Vision-Language Models'}, 'abstract': {'value': 'Vision-language models have in short time been established as powerful networks, demonstrating strong performance on a wide range of downstream tasks. A key factor behind their success is the learning of a joint embedding space where pairs of images and textual descriptions are contrastively aligned. Recent work has explored the geometry of the joint embedding space, finding that hyperbolic embeddings provide a compelling alternative to the commonly used Euclidean embeddings. Specifically, hyperbolic embeddings yield improved zero-shot generalization, better visual recognition, and more consistent semantic interpretations. In this paper, we conduct a deeper study into the hyperbolic embeddings and find that they open new doors for vision-language models. In particular, we find that hyperbolic vision-language models provide spatial awareness that Euclidean vision-language models lack, are better capable of dealing with ambiguity, and effectively discriminate between distributions. Our findings shed light on the greater potential of hyperbolic embeddings in large-scale settings, reaching beyond conventional down-stream tasks. Our code is available at https://github.com/saibr/hypvl'}, 'authors': {'value': ['Sarah Ibrahimi', 'Mina Ghadimi Atigh', 'Nanne Van Noord', 'Pascal Mettes', 'Marcel Worring']}, 'authorids': {'value': ['~Sarah_Ibrahimi1', '~Mina_Ghadimi_Atigh1', '~Nanne_Van_Noord1', '~Pascal_Mettes1', '~Marcel_Worring2']}, 'pdf': {'value': '/pdf/7a64d6d0db87a12265553b9b8d9604652461810b.pdf'}, 'submission_length': {'value': 'Long submission (more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
ibrahimi2024intriguing,
title={Intriguing Properties of Hyperbolic Embeddings in Vision-Language Models},
author={Sarah Ibrahimi and Mina Ghadimi Atigh and Nanne Van Noord and Pascal Mettes and Marcel Worring},
journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
