journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=73uyerai53},
note={}
}'}, 'assigned_action_editor': {'value': '~Yan_Liu1'}, 'code': {'value': 'https://github.com/grittibetti/TAP'}, 'paperhash': {'value': 'wang|tap_the_attention_patch_for_crossmodal_knowledge_transfer_from_unlabeled_modality'}}

{'title': {'value': 'A Survey on Transferability of Adversarial Examples Across Deep Neural Networks'}, 'abstract': {'value': "The emergence of Deep Neural Networks (DNNs) has revolutionized various domains by enabling the resolution of complex tasks spanning image recognition, natural language processing, and scientific problem-solving. However, this progress has also brought to light a concerning vulnerability: adversarial examples. These crafted inputs, imperceptible to humans, can manipulate machine learning models into making erroneous predictions, raising concerns for safety-critical applications. An intriguing property of this phenomenon is the transferability of adversarial examples, where perturbations crafted for one model can deceive another, often with a different architecture. This intriguing property enables ``black-box'' attacks which circumvents the need for detailed knowledge of the target model. This survey explores the landscape of the adversarial transferability of adversarial examples. We categorize existing methodologies to enhance adversarial transferability and discuss the fundamental principles guiding each approach. While the predominant body of research primarily concentrates on image classification, we also extend our discussion to encompass other vision tasks and beyond. Challenges and opportunities are discussed, highlighting the importance of fortifying DNNs against adversarial vulnerabilities in an evolving landscape."}, 'authors': {'value': ['Jindong Gu', 'Xiaojun Jia', 'Pau de Jorge', 'Wenqian Yu', 'Xinwei Liu', 'Avery Ma', 'Yuan Xun', 'Anjun Hu', 'Ashkan Khakzar', 'Zhijiang Li', 'Xiaochun Cao', 'Philip Torr']}, 'authorids': {'value': ['~Jindong_Gu1', '~Xiaojun_Jia1', '~Pau_de_Jorge1', '~Wenqian_Yu2', '~Xinwei_Liu2', '~Avery_Ma1', '~Yuan_Xun1', '~Anjun_Hu1', '~Ashkan_Khakzar1', '~Zhijiang_Li1', '~Xiaochun_Cao3', '~Philip_Torr1']}, 'pdf': {'value': '/pdf/217d656c25fca6fc72ebee624998dff4b4caa36d.pdf'}, 'submission_length': {'value': 'Long submission (more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
