journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=BQE4MTAfCE},
note={}
}'}, 'assigned_action_editor': {'value': '~Alp_Kucukelbir1'}, 'code': {'value': 'https://github.com/mackelab/amortized-decision-making'}, 'paperhash': {'value': 'gorecki|amortized_bayesian_decision_making_for_simulationbased_models'}}

{'title': {'value': 'Optimal Transport Perturbations for Safe Reinforcement Learning with Robustness Guarantees'}, 'abstract': {'value': 'Robustness and safety are critical for the trustworthy deployment of deep reinforcement learning. Real-world decision making applications require algorithms that can guarantee robust performance and safety in the presence of general environment disturbances, while making limited assumptions on the data collection process during training. In order to accomplish this goal, we introduce a safe reinforcement learning framework that incorporates robustness through the use of an optimal transport cost uncertainty set. We provide an efficient implementation based on applying Optimal Transport Perturbations to construct worst-case virtual state transitions, which does not impact data collection during training and does not require detailed simulator access. In experiments on continuous control tasks with safety constraints, our approach demonstrates robust performance while significantly improving safety at deployment time compared to standard safe reinforcement learning.'}, 'authors': {'value': ['James Queeney', 'Erhan Can Ozcan', 'Ioannis Paschalidis', 'Christos Cassandras']}, 'authorids': {'value': ['~James_Queeney1', '~Erhan_Can_Ozcan1', '~Ioannis_Paschalidis1', '~Christos_Cassandras1']}, 'pdf': {'value': '/pdf/954617099c7d2db45b3b1a36f6edff65527d4992.pdf'}, 'submission_length': {'value': 'Regular submission (no more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
