journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=TZdEgwZ6f3},
note={}
}'}, 'assigned_action_editor': {'value': '~Zhe_Gan1'}, 'paperhash': {'value': 'smith|continual_diffusion_continual_customization_of_texttoimage_diffusion_with_clora'}}

{'title': {'value': 'The Missing U for Efficient Diffusion Models'}, 'abstract': {'value': 'Diffusion Probabilistic Models stand as a critical tool in generative modelling, enabling the generation of complex data distributions. This family of generative models yields record-breaking performance in tasks such as image synthesis, video generation, and molecule design. Despite their capabilities, their efficiency, especially in the reverse process, remains a challenge due to slow convergence rates and high computational costs. In this paper, we introduce an approach that leverages continuous dynamical systems to design a novel denoising network for diffusion models that is more parameter-efficient, exhibits faster convergence, and demonstrates increased noise robustness. Experimenting with Denoising Diffusion Probabilistic Models (DDPMs), our framework operates with approximately a quarter of the parameters, and $\sim$ 30\% of the Floating Point Operations (FLOPs) compared to standard U-Nets in DDPMs. Furthermore, our model is notably faster in inference than the baseline when measured in fair and equal conditions. We also provide a mathematical intuition as to why our proposed reverse process is faster as well as a mathematical discussion of the empirical tradeoffs in the denoising downstream task. Finally, we argue that our method is compatible with existing performance enhancement techniques, enabling further improvements in efficiency, quality, and speed.'}, 'authors': {'value': ['Sergio Calvo Ordoñez', 'Chun-Wun Cheng', 'Jiahao Huang', 'Lipei Zhang', 'Guang Yang', 'Carola-Bibiane Schönlieb', 'Angelica I Aviles-Rivero']}, 'authorids': {'value': ['~Sergio_Calvo_Ordoñez1', '~Chun-Wun_Cheng1', '~Jiahao_Huang1', '~Lipei_Zhang1', '~Guang_Yang1', '~Carola-Bibiane_Schönlieb1', '~Angelica_I_Aviles-Rivero1']}, 'pdf': {'value': '/pdf/aeea08d8af033d8cba04815abc87f8959e25adfa.pdf'}, 'submission_length': {'value': 'Regular submission (no more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
ordo{\~n}ez2024the,
title={The Missing U for Efficient Diffusion Models},
author={Sergio Calvo Ordo{\~n}ez and Chun-Wun Cheng and Jiahao Huang and Lipei Zhang and Guang Yang and Carola-Bibiane Sch{\"o}nlieb and Angelica I Aviles-Rivero},
journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=Y4YWzBiTEV},
