journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=vgthYeRBAF},
note={}
}'}, 'assigned_action_editor': {'value': '~Danny_Tarlow1'}, 'paperhash': {'value': 'kuznedelev|accurate_neural_network_pruning_requires_rethinking_sparse_optimization'}}

{'title': {'value': 'Multi-conditioned Graph Diffusion for Neural Architecture Search'}, 'abstract': {'value': 'Neural architecture search automates the design of neural network architectures usually by exploring a large and thus complex architecture search space. To advance the architecture search, we present a graph diffusion-based NAS approach that uses discrete conditional graph diffusion processes to generate high-performing neural network architectures. We then propose a multi-conditioned classifier-free guidance approach applied to graph diffusion networks to jointly impose constraints such as high accuracy and low hardware latency. Unlike the related work, our method is completely differentiable and requires only a single model training. In our evaluations, we show promising results on six standard benchmarks, yielding novel and unique architectures at a fast speed, i.e. less than 0.2 seconds per architecture. Furthermore, we demonstrate the generalisability and efficiency of our method through experiments on ImageNet dataset.'}, 'authors': {'value': ['Rohan Asthana', 'Joschua Conrad', 'Youssef Dawoud', 'Maurits Ortmanns', 'Vasileios Belagiannis']}, 'authorids': {'value': ['~Rohan_Asthana1', '~Joschua_Conrad1', '~Youssef_Dawoud1', '~Maurits_Ortmanns1', '~Vasileios_Belagiannis1']}, 'pdf': {'value': '/pdf/c10e5e3d935f4bda98f74b044be3be1624a2e259.pdf'}, 'submission_length': {'value': 'Long submission (more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
