author={Recep Can Yavas and Vincent Y. F. Tan},
journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=Igxp7FC8uf},
note={}
}'}, 'assigned_action_editor': {'value': '~Chicheng_Zhang1'}, 'changes_since_last_submission': {'value': 'The example for the asymptotic expansion in eq. (20) is corrected.'}, 'code': {'value': 'https://github.com/recepcyavas/TMLR_sparse_linear_bandit'}, 'license': {'value': 'Creative Commons Attribution 4.0 International (CC BY 4.0)'}, 'paperhash': {'value': 'yavas|fixedbudget_bestarm_identification_in_sparse_linear_bandits'}}

{'title': {'value': 'Improving and generalizing flow-based generative models with minibatch optimal transport'}, 'abstract': {'value': 'Continuous normalizing flows (CNFs) are an attractive generative modeling technique, but they have been held back by limitations in their simulation-based maximum likelihood training. We introduce the generalized conditional flow matching (CFM) technique, a family of simulation-free training objectives for CNFs. CFM features a stable regression objective like that used to train the stochastic flow in diffusion models but enjoys the efficient inference of deterministic flow models. In contrast to both diffusion models and prior CNF training algorithms, CFM does not require the source distribution to be Gaussian or require evaluation of its density. A variant of our objective is optimal transport CFM (OT-CFM), which creates simpler flows that are more stable to train and lead to faster inference, as evaluated in our experiments. Furthermore, we show that when the true OT plan is available, our OT-CFM method approximates dynamic OT. Training CNFs with CFM improves results on a variety of conditional and unconditional generation tasks, such as inferring single cell dynamics, unsupervised image translation, and Schrödinger bridge inference. The Python code is available at https://github.com/atong01/conditional-flow-matching.'}, 'authors': {'value': ['Alexander Tong', 'Kilian FATRAS', 'Nikolay Malkin', 'Guillaume Huguet', 'Yanlei Zhang', 'Jarrid Rector-Brooks', 'Guy Wolf', 'Yoshua Bengio']}, 'authorids': {'value': ['~Alexander_Tong1', '~Kilian_FATRAS1', '~Nikolay_Malkin1', '~Guillaume_Huguet1', '~Yanlei_Zhang1', '~Jarrid_Rector-Brooks2', '~Guy_Wolf1', '~Yoshua_Bengio1']}, 'pdf': {'value': '/pdf/dc6be529e2849f1257ce18efde8e9a5ca78f4438.pdf'}, 'submission_length': {'value': 'Regular submission (no more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
tong2024improving,
title={Improving and generalizing flow-based generative models with minibatch optimal transport},
author={Alexander Tong and Kilian FATRAS and Nikolay Malkin and Guillaume Huguet and Yanlei Zhang and Jarrid Rector-Brooks and Guy Wolf and Yoshua Bengio},
journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=CD9Snc73AW},
note={Expert Certification}
}'}, 'assigned_action_editor': {'value': '~Alain_Durmus1'}, 'certifications': {'value': ['Expert Certification']}, 'expert_reviewers': {'value': ['~Yoshua_Bengio1']}, 'paperhash': {'value': 'tong|improving_and_generalizing_flowbased_generative_models_with_minibatch_optimal_transport'}}

{'title': {'value': 'Q-Learning for Stochastic Control under General Information Structures and Non-Markovian Environments'}, 'abstract': {'value': 'As a primary contribution, we present a convergence theorem for stochastic iterations, and in particular, Q-learning iterates, under a general, possibly non-Markovian, stochastic environment. Our conditions for convergence involve an ergodicity and a positivity criterion. We provide a precise characterization on the limit of the iterates and conditions on the environment and initializations for convergence. As our second contribution, we discuss the implications and applications of this theorem to a variety of stochastic control problems with non-Markovian environments involving (i) quantized approximations of fully observed Markov Decision Processes (MDPs) with continuous spaces (where quantization break down the Markovian structure), (ii) quantized approximations of belief-MDP reduced partially observable MDPS (POMDPs) with weak Feller continuity and a mild version of filter stability (which requires the knowledge of the model by the controller), (iii) finite window approximations of POMDPs under a uniform controlled filter stability (which does not require the knowledge of the model), and (iv) for multi-agent models where convergence of learning dynamics to a new class of equilibria, subjective Q-learning equilibria, will be studied. In addition to the convergence theorem, some implications of the theorem above are new to the literature and others are interpreted as applications of the convergence theorem. Some open problems are noted.'}, 'authors': {'value': ['Ali Devran Kara', 'Serdar Yuksel']}, 'authorids': {'value': ['~Ali_Devran_Kara1', '~Serdar_Yuksel1']}, 'pdf': {'value': '/pdf/271bdc07e0a0ba136281dd9cec5ed34e2fd750ba.pdf'}, 'submission_length': {'value': 'Long submission (more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
