title={Enhancing Robustness to Class-Conditional Distribution Shift in Long-Tailed Recognition},
author={Keliang Li and Hong Chang and Shiguang Shan and Xilin CHEN},
journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=n2gAD8Fdzk},
note={}
}'}, 'assigned_action_editor': {'value': '~Antoni_B._Chan1'}, 'license': {'value': 'Creative Commons Attribution 4.0 International (CC BY 4.0)'}, 'paperhash': {'value': 'li|enhancing_robustness_to_classconditional_distribution_shift_in_longtailed_recognition'}}

{'title': {'value': 'LLM-grounded Diffusion: Enhancing Prompt Understanding of Text-to-Image Diffusion Models with Large Language Models'}, 'abstract': {'value': "Recent advancements in text-to-image diffusion models have yielded impressive results in generating realistic and diverse images. However, these models still struggle with complex prompts, such as those that involve numeracy and spatial reasoning. This work proposes to enhance prompt understanding capabilities in diffusion models. Our method leverages a pretrained large language model (LLM) for grounded generation in a novel two-stage process. In the first stage, the LLM generates a scene layout that comprises captioned bounding boxes from a given prompt describing the desired image. In the second stage, a novel controller guides an off-the-shelf diffusion model for layout-grounded image generation. Both stages utilize existing pretrained models without additional model parameter optimization. Our method significantly outperforms the base diffusion model and several strong baselines in accurately generating images according to prompts that require various capabilities, doubling the generation accuracy across four tasks on average. Furthermore, our method enables instruction-based multi-round scene specification and can handle prompts in languages not supported by the underlying diffusion model. We anticipate that our method will unleash users' creativity by accurately following more complex prompts. Our code, demo, and benchmark are available at: https://llm-grounded-diffusion.github.io"}, 'authors': {'value': ['Long Lian', 'Boyi Li', 'Adam Yala', 'Trevor Darrell']}, 'authorids': {'value': ['~Long_Lian1', '~Boyi_Li1', '~Adam_Yala1', '~Trevor_Darrell2']}, 'pdf': {'value': '/pdf/a3cf2bb6aaeb2b58e4aabbc79889496909c06ffe.pdf'}, 'submission_length': {'value': 'Regular submission (no more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': 