journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2023},
url={https://openreview.net/forum?id=AXtFeYjboj},
note={Survey Certification}
}'}, 'assigned_action_editor': {'value': '~Greg_Durrett1'}, 'certifications': {'value': ['Survey Certification']}, 'license': {'value': 'Creative Commons Attribution 4.0 International (CC BY 4.0)'}, 'paperhash': {'value': 'ghosal|a_survey_on_the_possibilities_impossibilities_of_aigenerated_text_detection'}}

{'title': {'value': 'Correlation Clustering with Active Learning of Pairwise Similarities'}, 'abstract': {'value': 'Correlation clustering is a well-known unsupervised learning setting that deals with positive and negative pairwise similarities. In this paper, we study the case where the pairwise similarities are not given in advance and must be queried in a cost-efficient way. Thereby, we develop a generic active learning framework for this task that benefits from several advantages, e.g., flexibility in the type of feedback that a user/annotator can provide, adaptation to any correlation clustering algorithm and query strategy, and robustness to noise. In addition, we propose and analyze a number of novel query strategies suited to this setting. We demonstrate the effectiveness of our framework and the proposed query strategies via several experimental studies.'}, 'authors': {'value': ['Linus Aronsson', 'Morteza Haghir Chehreghani']}, 'authorids': {'value': ['~Linus_Aronsson1', '~Morteza_Haghir_Chehreghani2']}, 'pdf': {'value': '/pdf/5bc504e379a57745de6ae4be2fe9e10702d7d751.pdf'}, 'submission_length': {'value': 'Long submission (more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
