author={Francesco Di Giovanni and T. Konstantin Rusch and Michael Bronstein and Andreea Deac and Marc Lackenby and Siddhartha Mishra and Petar Veli{\v{c}}kovi{\'c}},
journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=KJRoQvRWNs},
note={}
}"}, 'assigned_action_editor': {'value': '~Alessandro_Sperduti1'}, 'paperhash': {'value': 'giovanni|how_does_oversquashing_affect_the_power_of_gnns'}}

{'title': {'value': 'Continual HyperTransformer: A Meta-Learner for Continual Few-Shot Learning'}, 'abstract': {'value': 'We focus on the problem of learning without forgetting from multiple tasks arriving sequentially, where each task is defined using a few-shot episode of novel or already seen classes. We approach this problem using the recently published HyperTransformer (HT), a Transformer-based hypernetwork that generates specialized task-specific CNN weights directly from the support set. In order to learn from a continual sequence of tasks, we propose to recursively re-use the generated weights as input to the HT for the next task. This way, the generated CNN weights themselves act as a representation of previously learned tasks, and the HT is trained to update these weights so that the new task can be learned without forgetting past tasks. This approach is different from most continual learning algorithms that typically rely on using replay buffers, weight regularization or task-dependent architectural changes. We demonstrate that our proposed Continual HyperTransformer method equipped with a prototypical loss is capable of learning and retaining knowledge about past tasks for a variety of scenarios, including learning from mini-batches, and task-incremental and class-incremental learning scenarios.'}, 'authors': {'value': ['Max Vladymyrov', 'Andrey Zhmoginov', 'Mark Sandler']}, 'authorids': {'value': ['~Max_Vladymyrov1', '~Andrey_Zhmoginov1', '~Mark_Sandler1']}, 'pdf': {'value': '/pdf/a8acb5eb04ab811a86b00e2caa5f958d526b6f73.pdf'}, 'submission_length': {'value': 'Regular submission (no more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
vladymyrov2024continual,
title={Continual HyperTransformer: A Meta-Learner for Continual Few-Shot Learning},
author={Max Vladymyrov and Andrey Zhmoginov and Mark Sandler},
journal={Transactions on Machine Learning Research},
