author={Gavin Brown and Riccardo Ali},
journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=4TnFbv16hK},
note={}
}'}, 'assigned_action_editor': {'value': '~Trevor_Campbell1'}, 'changes_since_last_submission': {'value': 'Several final changes, as detailed in reply to action editor below.
Funding acknowledgements added. One reference added.'}, 'code': {'value': 'https://github.com/profgavinbrown/ondecompositions'}, 'license': {'value': 'Creative Commons Attribution 4.0 International (CC BY 4.0)'}, 'paperhash': {'value': 'brown|biasvariance_is_not_the_same_as_approximationestimation'}}

{'title': {'value': 'TensorVAE: a simple and efficient generative model for conditional molecular conformation generation'}, 'abstract': {'value': 'Efficient generation of 3D conformations of a molecule from its 2D graph is a key challenge in in-silico drug discovery. Deep learning (DL) based generative modelling has recently become a potent tool to tackling this challenge. However, many existing DL-based methods are either indirect–leveraging inter-atomic distances or direct–but requiring numerous sampling steps to generate conformations. In this work, we propose a simple model abbreviated TensorVAE capable of generating conformations directly from a 2D molecular graph in a single step. The main novelty of the proposed method is focused on feature engineering. We develop a novel encoding and feature extraction mechanism relying solely on standard convolution operation to generate token-like feature vector for each atom. These feature vectors are then transformed through standard transformer encoders under a conditional Variational Autoencoder framework for generating conformations directly. We show through experiments on two benchmark datasets that with intuitive feature engineering, a relatively simple and standard model can provide promising generative capability outperforming more than a dozen state-of-the-art models employing more sophisticated and specialized generative architecture.'}, 'authors': {'value': ['Hongyang Yu', 'Hongjiang Yu']}, 'authorids': {'value': ['~Hongyang_Yu2', '~Hongjiang_Yu1']}, 'pdf': {'value': '/pdf/704330d3b139a9878ed5f21eab426e29f8bb98de.pdf'}, 'submission_length': {'value': 'Long submission (more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
yu2024tensorvae,
