journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2024},
url={https://openreview.net/forum?id=KhMLfEIoUm},
note={}
}'}, 'assigned_action_editor': {'value': '~Ruoyu_Sun1'}, 'changes_since_last_submission': {'value': 'This is the de-anonymized camera ready revision.'}, 'code': {'value': 'https://github.com/cvxgrp/dsp'}, 'license': {'value': 'Creative Commons Attribution 4.0 International (CC BY 4.0)'}, 'paperhash': {'value': 'schiele|disciplined_saddle_programming'}}

{'title': {'value': 'Cross-client Label Propagation for Transductive and Semi-Supervised Federated Learning'}, 'abstract': {'value': 'We present Cross-Client Label Propagation (XCLP), a new method for transductive and semi-supervised federated learning. XCLP estimates a data graph jointly from the data of multiple clients and computes labels for the unlabeled data by propagating label information across the graph. To avoid clients having to share their data with anyone, XCLP employs two cryptographically secure protocols: secure Hamming distance computation and secure summation. We demonstrate two distinct applications of XCLP within federated learning. In the first, we use it in a one-shot way to predict labels for unseen test points. In the second, we use it to repeatedly pseudo-label unlabeled training data in a federated semi-supervised setting. Experiments on both real federated and standard benchmark datasets show that in both applications XCLP achieves higher classification accuracy than alternative approaches.'}, 'authors': {'value': ['Jonathan Scott', 'Michelle Yeo', 'Christoph H Lampert']}, 'authorids': {'value': ['~Jonathan_Scott1', '~Michelle_Yeo1', '~Christoph_H_Lampert1']}, 'pdf': {'value': '/pdf/bfffb1b9925500f052028fcc36ba27406c3924f0.pdf'}, 'submission_length': {'value': 'Regular submission (no more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
