journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2023},
url={https://openreview.net/forum?id=U4XgzRjfF1},
note={}
}"}, 'assigned_action_editor': {'value': '~Simon_Lacoste-Julien1'}, 'changes_since_last_submission': {'value': 'Upload camera-ready version of the paper.'}, 'code': {'value': 'https://github.com/RemiLELUC/ConditionedSGD'}, 'license': {'value': 'Creative Commons Attribution 4.0 International (CC BY 4.0)'}, 'paperhash': {'value': 'leluc|asymptotic_analysis_of_conditioned_stochastic_gradient_descent'}}

{'title': {'value': 'Meta-Calibration: Learning of Model Calibration Using Differentiable Expected Calibration Error'}, 'abstract': {'value': 'Calibration of neural networks is a topical problem that is becoming more and more important as neural networks increasingly underpin real-world applications. The problem is especially noticeable when using modern neural networks, for which there is a significant difference between the confidence of the model and the probability of correct prediction. Various strategies have been proposed to improve calibration, yet accurate calibration remains challenging. We propose a novel framework with two contributions: introducing a new differentiable surrogate for expected calibration error (DECE) that allows calibration quality to be directly optimised, and a meta-learning framework that uses DECE to optimise for validation set calibration with respect to model hyper-parameters. The results show that we achieve competitive performance with existing calibration approaches. Our framework opens up a new avenue and toolset for tackling calibration, which we believe will inspire further work on this important challenge.'}, 'authors': {'value': ['Ondrej Bohdal', 'Yongxin Yang', 'Timothy Hospedales']}, 'authorids': {'value': ['~Ondrej_Bohdal1', '~Yongxin_Yang1', '~Timothy_Hospedales1']}, 'pdf': {'value': '/pdf/f9266913213b59a701bf7cab86d908318fa544ab.pdf'}, 'submission_length': {'value': 'Regular submission (no more than 12 pages of main content)'}, 'supplementary_material': {'value': '/attachment/6ccf07be9d623bc1bf0de0a865400ecdcb1ad28f.zip'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
