}"}, 'assigned_action_editor': {'value': '~Ole_Winther1'}, 'code': {'value': 'https://github.com/graphcore/ogb-lsc-pcqm4mv2'}, 'license': {'value': 'Creative Commons Attribution 4.0 International (CC BY 4.0)'}, 'paperhash': {'value': 'masters|gps_reviving_the_art_of_message_passing_for_molecular_property_prediction'}}

{'title': {'value': 'V1T: large-scale mouse V1 response prediction using a Vision Transformer'}, 'abstract': {'value': 'Accurate predictive models of the visual cortex neural response to natural visual stimuli remain a challenge in computational neuroscience. In this work, we introduce $V{\small 1}T$, a novel Vision Transformer based architecture that learns a shared visual and behavioral representation across animals. We evaluate our model on two large datasets recorded from mouse primary visual cortex and outperform previous convolution-based models by more than 12.7% in prediction performance. Moreover, we show that the self-attention weights learned by the Transformer correlate with the population receptive fields. Our model thus sets a new benchmark for neural response prediction and can be used jointly with behavioral and neural recordings to reveal meaningful characteristic features of the visual cortex.'}, 'authors': {'value': ['Bryan M. Li', 'Isabel Maria Cornacchia', 'Nathalie Rochefort', 'Arno Onken']}, 'authorids': {'value': ['~Bryan_M._Li1', '~Isabel_Maria_Cornacchia1', '~Nathalie_Rochefort1', '~Arno_Onken1']}, 'pdf': {'value': '/pdf/75400e7b1ae6a3f91c7b5451beec941df01a196b.pdf'}, 'submission_length': {'value': 'Regular submission (no more than 12 pages of main content)'}, 'supplementary_material': {'value': '/attachment/e4f812a05a917d4b5f29f1945ca7ede8b7eeb1f6.zip'}, 'changes_since_last_submission': {'value': 'N/A'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
