journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2023},
url={https://openreview.net/forum?id=f4VyYhkRvi},
note={}
}'}, 'assigned_action_editor': {'value': '~Kangwook_Lee1'}, 'code': {'value': 'https://github.com/akshajkumarv/MinDiff'}, 'certifications': {'value': []}, 'license': {'value': 'Creative Commons Attribution 4.0 International (CC BY 4.0)'}, 'paperhash': {'value': 'veldanda|fairness_via_inprocessing_in_the_overparameterized_regime_a_cautionary_tale_with_mindiff_loss'}}

{'title': {'value': 'Feature-Attending Recurrent Modules for Generalization in Reinforcement Learning'}, 'abstract': {'value': 'Many important tasks are defined in terms of object. To generalize across these tasks, a reinforcement learning (RL) agent needs to exploit the structure that the objects induce. Prior work has either hard-coded object-centric features, used complex object-centric generative models, or updated state using local spatial features. However, these approaches have had limited success in enabling general RL agents. Motivated by this, we introduce “Feature- Attending Recurrent Modules” (FARM), an architecture for learning state representations that relies on simple, broadly applicable inductive biases for capturing spatial and temporal regularities. FARM learns a state representation that is distributed across multiple modules that each attend to spatiotemporal features with an expressive feature attention mechanism. We show that this improves an RL agent’s ability to generalize across object-centric tasks. We study task suites in both 2D and 3D environments and find that FARM better generalizes compared to competing architectures that leverage attention or multiple modules.'}, 'authors': {'value': ['Wilka Torrico Carvalho', 'Andrew Kyle Lampinen', 'Kyriacos Nikiforou', 'Felix Hill', 'Murray Shanahan']}, 'authorids': {'value': ['~Wilka_Torrico_Carvalho1', '~Andrew_Kyle_Lampinen1', '~Kyriacos_Nikiforou1', '~Felix_Hill1', '~Murray_Shanahan1']}, 'pdf': {'value': '/pdf/ed058ee8ab02d5e94dc83a19629e58d6ecf40ef4.pdf'}, 'submission_length': {'value': 'Regular submission (no more than 12 pages of main content)'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
carvalho2023featureattending,
title={Feature-Attending Recurrent Modules for Generalization in Reinforcement Learning},
