title={Transformer for Partial Differential Equations{\textquoteright} Operator Learning},
author={Zijie Li and Kazem Meidani and Amir Barati Farimani},
journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2023},
url={https://openreview.net/forum?id=EPPqt3uERT},
note={}
}'}, 'assigned_action_editor': {'value': '~Tie-Yan_Liu1'}, 'code': {'value': 'https://github.com/BaratiLab/OFormer'}, 'certifications': {'value': []}, 'license': {'value': 'Creative Commons Attribution 4.0 International (CC BY 4.0)'}, 'paperhash': {'value': 'li|transformer_for_partial_differential_equations_operator_learning'}}

{'title': {'value': 'NovelCraft: A Dataset for Novelty Detection and Discovery in Open Worlds'}, 'abstract': {'value': 'In order for artificial agents to successfully perform tasks in changing environments, they must be able to both detect and adapt to novelty. However, visual novelty detection research often only evaluates on repurposed datasets such as CIFAR-10 originally intended for object classification, where images focus on one distinct, well-centered object. New benchmarks are needed to represent the challenges of navigating the complex scenes of an open world. Our new NovelCraft dataset contains multimodal episodic data of the images and symbolic world-states seen by an agent completing a pogo stick assembly task within a modified Minecraft environment. In some episodes, we insert novel objects of varying size within the complex 3D scene that may impact gameplay. Our visual novelty detection benchmark finds that methods that rank best on popular area-under-the-curve metrics may be outperformed by simpler alternatives when controlling false positives matters most. Further multimodal novelty detection experiments suggest that methods that fuse both visual and symbolic information can improve time until detection as well as overall discrimination. Finally, our evaluation of recent generalized category discovery methods suggests that adapting to new imbalanced categories in complex scenes remains an exciting open problem.'}, 'authors': {'value': ['Patrick Feeney', 'Sarah Schneider', 'Panagiotis Lymperopoulos', 'Liping Liu', 'Matthias Scheutz', 'Michael C Hughes']}, 'authorids': {'value': ['~Patrick_Feeney1', '~Sarah_Schneider1', '~Panagiotis_Lymperopoulos1', '~Liping_Liu1', '~Matthias_Scheutz1', '~Michael_C_Hughes1']}, 'pdf': {'value': '/pdf/cd15445c155c2a6b6ef516252903b039b6ab325c.pdf'}, 'submission_length': {'value': 'Regular submission (no more than 12 pages of main content)'}, 'supplementary_material': {'value': '/attachment/0d3701ca35b238b6f33bf23f9d55d88b