journal={Transactions on Machine Learning Research},
issn={2835-8856},
year={2023},
url={https://openreview.net/forum?id=k5m8xXTOrC},
note={}
}'}, 'assigned_action_editor': {'value': '~Raman_Arora1'}, 'certifications': {'value': []}, 'license': {'value': 'Creative Commons Attribution 4.0 International (CC BY 4.0)'}, 'paperhash': {'value': 'xie|solving_a_special_type_of_optimal_transport_problem_by_a_modified_hungarian_algorithm', 'readers': ['everyone']}}

{'title': {'value': 'Learning to Look by Self-Prediction'}, 'abstract': {'value': "We present a method for learning active vision skills, to move the camera to observe a robot's sensors from informative points of view, without external rewards or labels. We do this by jointly training a visual predictor network, which predicts future returns of the sensors using pixels, and a camera control agent, which we reward using the negative error of the predictor. The agent thus moves the camera to points of view that are most predictive for a chosen sensor, which we select using a conditioning input to the agent. We observe that despite this noisy learned reward function, the learned policies a exhibit competence by reliably framing the sensor in a specific location in the view, an emergent location which we call a behavioral fovea. We find that replacing the conventional camera with a foveal camera further increases the policies' precision."}, 'authors': {'value': ['Matthew Koichi Grimes', 'Joseph Varughese Modayil', 'Piotr W Mirowski', 'Dushyant Rao', 'Raia Hadsell']}, 'authorids': {'value': ['~Matthew_Koichi_Grimes1', '~Joseph_Varughese_Modayil1', '~Piotr_W_Mirowski1', '~Dushyant_Rao1', '~Raia_Hadsell2']}, 'pdf': {'value': '/pdf/9ff3b3324d57caadc75dcee5492b6e661f17808b.pdf'}, 'submission_length': {'value': 'Long submission (more than 12 pages of main content)'}, 'supplementary_material': {'value': '/attachment/75de47b977744627c5e17788c7bb9d93461ba814.zip'}, 'venue': {'value': 'Accepted by TMLR'}, 'venueid': {'value': 'TMLR'}, '_bibtex': {'value': '@article{
